with exploded as (select id, host, log_ts, latency_ms, k, value from app_logs lateral view explode(context) e as k, value), enriched as (select *, round(latency_ms / sum(latency_ms) over (partition by k), 4) as latency_ms_share, row_number() over (order by latency_ms, id, k) as row_seq, min(latency_ms) over (partition by k) as k_min_latency_ms, round(latency_ms / sum(latency_ms) over (partition by host), 4) as latency_ms_share_2 from exploded), gaps as (select *, case when log_ts - lag(log_ts) over (partition by host order by log_ts, id, k) > interval 15 minutes then 1 else 0 end as is_new_burst from enriched), sessionized as (select *, sum(is_new_burst) over (partition by host order by log_ts, id, k rows between unbounded preceding and current row) as island_id from gaps), latest as (select * from (select *, row_number() over (partition by host, k order by latency_ms_share_2 desc, id, k) as row_num from sessionized) t where row_num = 1), filtered as (select id, log_ts, latency_ms, k, latency_ms_share, row_seq, k_min_latency_ms, latency_ms_share_2, is_new_burst, island_id, row_num, case when island_id >= 6 then 'High' when island_id >= 1 then 'Medium' else 'Low' end as island_id_level, coalesce(k, 'UNKNOWN') as k_clean from latest where log_ts > date '2025-06-01' and k is not null), flagged as (select *, case when lag(log_ts) over (partition by k order by log_ts, id, k) is null or log_ts > lag(log_ts) over (partition by k order by log_ts, id, k) + interval '20' minute then 1 else 0 end as new_group_flag from filtered), sessionized_app_logs as (select *, sum(new_group_flag) over (partition by k order by log_ts, id, k rows between unbounded preceding and current row) as session_no from flagged), valid as (select id, log_ts, latency_ms, k, row_seq, k_min_latency_ms, is_new_burst, row_num, island_id_level, k_clean, new_group_flag, session_no, greatest(row_num, latency_ms) as greatest_row_num_latency_ms, k_min_latency_ms + island_id as k_min_latency_ms_plus_island_id, coalesce(k, 'NONE') as resolved_k from sessionized_app_logs where log_ts >= date '2025-06-01' and k is not null) select id, latency_ms, k, row_seq, is_new_burst, row_num, k_clean, new_group_flag, session_no from valid order by row_num desc nulls last
